'use client';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import FormFieldsBuilder from './FormFieldsBuilder';

const API = (process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000/api').replace(/\/$/, '');
const TABS = [
 ['overview','Overview'],['pages','Pages & Layouts'],['branches','Branches'],['contact','Contact Page'],['forms','Form Builder'],['templates','Email Templates'],['enquiries','Enquiries'],['leads','Leads'],['packages','Service Packages'],['documents','Quotes & Invoices'],['email','Email Setup'],['profile','Profile & Settings'],['users','Team Users']
];
const DEFAULT_SECTIONS = JSON.stringify([
 { id:'hero', type:'hero', label:'Hero', visible:true, data:{ eyebrow:'FSG ENVIRONMENTAL', title:'New page headline.', text:'Add the summary for this page.', image:'/images/services-hero.webp', primaryLabel:'Request a scope review', primaryHref:'/contact' } },
 { id:'intro', type:'richText', label:'Intro', visible:true, data:{ eyebrow:'INTRODUCTION', title:'Section heading.', text:'Write the content for this page section.' } },
 { id:'cta', type:'cta', label:'Next step', visible:true, data:{ eyebrow:'THE NEXT STEP', title:'Plan your next step.', text:'Tell us about your site and the scope you need.', buttonLabel:'Contact FSG', buttonHref:'/contact' } }
], null, 2);
const DEFAULT_FIELDS = JSON.stringify([
 { key:'name', label:'Your name', type:'text', placeholder:'Full name', required:true, width:'half', order:1 },
 { key:'email', label:'Email', type:'email', placeholder:'name@company.com', required:true, width:'half', order:2 },
 { key:'phone', label:'Phone', type:'tel', placeholder:'Your contact number', required:false, width:'half', order:3 },
 { key:'message', label:'Message', type:'textarea', placeholder:'Tell us about the work.', required:true, width:'full', order:4 }
], null, 2);
const DEFAULT_TEMPLATE = { name:'New email template', key:'new-template', purpose:'custom', trigger:'manual', enabled:true, to:'{{customer.email}}', cc:'', bcc:'', fromName:'', fromEmail:'', replyTo:'', subject:'Message from FSG Environmental', headerHtml:'<h2 style="margin:0">FSG ENVIRONMENTAL</h2>', bodyHtml:'<p>Hello {{customer.name}},</p><p>Write your message here.</p>', footerHtml:'<p>Future Starts Green</p>', formSlugs:[], layoutOrder:['header','body','footer'] };
const DEFAULT_PAGE = { title:'New page', slug:'new-page', navLabel:'New page', pageType:'standard', status:'draft', showInNavigation:false, sortOrder:100, seo:{title:'',description:'',canonical:'',noIndex:false}, sections:[] };
const DEFAULT_BRANCH = { name:'New branch', label:'FSG LOCATION', address:'', city:'', region:'', postalCode:'', country:'United Kingdom', phone:'', email:'', mapUrl:'', openingHours:'', visible:true, showOnContact:true, sortOrder:100 };
const DEFAULT_FORM = { name:'New form', slug:'new-form', description:'', submitLabel:'Send request', successMessage:'Thank you. Your request has been received.', status:'draft', pageSlugs:['contact'], placement:'inline', layout:{columns:2,style:'reference',formBackground:'#ffffff',fieldBackground:'#fbfcfa',fieldBorderColor:'#d7e0d6',accentColor:'#238638',buttonBackground:'#61d94e',buttonTextColor:'#06170c',textColor:'#101b16',borderRadius:0}, fields:JSON.parse(DEFAULT_FIELDS), autoReplyTemplateId:'', notificationTemplateId:'' };

async function request(path, options={}) {
 const response = await fetch(`${API}${path}`, { credentials:'include', ...options, headers:{ ...(options.body && !(options.body instanceof FormData) ? {'Content-Type':'application/json'} : {}), ...(options.headers || {}) } });
 const data = await response.json().catch(()=>({}));
 if (!response.ok) throw new Error(data.message || `Request failed (${response.status})`);
 return data;
}
const json = value => JSON.stringify(value ?? {}, null, 2);

export default function AdminWorkspace(){
 const router = useRouter(); const [tab,setTab] = useState('overview'); const [user,setUser] = useState(null); const [data,setData] = useState({}); const [selected,setSelected] = useState(null); const [draft,setDraft] = useState(null); const [busy,setBusy] = useState(false); const [notice,setNotice] = useState(''); const [error,setError] = useState(''); const [query,setQuery] = useState('');
 const [pageSections,setPageSections] = useState(DEFAULT_SECTIONS); const [formFields,setFormFields] = useState(DEFAULT_FIELDS); const [smtp,setSmtp] = useState({host:'',port:587,secure:false,user:'',password:'',fromName:'FSG Environmental',fromEmail:'',notificationTo:'',replyTo:''});
 const [reply,setReply] = useState({to:'',fromName:'FSG Environmental',fromEmail:'',subject:'',message:''}); const [selectedReplyTemplate,setSelectedReplyTemplate] = useState(''); const [docItemsJson,setDocItemsJson] = useState('[]'); const [docSendTo,setDocSendTo] = useState(''); const [packageItemsJson,setPackageItemsJson] = useState('[]'); const [teamUser,setTeamUser] = useState({name:'',email:'',password:'',role:'admin'}); const [profile,setProfile] = useState({name:'',email:'',currentPassword:'',newPassword:''}); const [siteSettings,setSiteSettings] = useState({companyName:'FSG Environmental',logoUrl:'',website:'',phone:'',email:'',address:'',currency:'GBP',taxRate:20,quotePrefix:'FSG-Q',invoicePrefix:'FSG-I'});
 const tell = (message) => { setNotice(message); setError(''); };
 const fail = (message) => { setError(message); setNotice(''); };
 const load = useCallback(async (key=tab) => {
  setBusy(true); setError('');
  try {
   if (key==='overview') { const d=await request('/admin/dashboard'); setData(v=>({...v,overview:d.counts})); }
   if (key==='pages'||key==='branches'||key==='forms'||key==='templates'||key==='packages'||key==='enquiries'||key==='leads') { const path=key==='templates'?'email-templates':key; const d=await request(`/admin/${path}`); setData(v=>({...v,[key]:d.items||[]})); if(key==='enquiries'||key==='forms'){const t=await request('/admin/email-templates');setData(v=>({...v,templates:t.items||[]}));} }
   if (key==='contact') { const [d,f]=await Promise.all([request('/admin/contact-settings'),request('/admin/forms')]); setData(v=>({...v,contact:d.item,contactForms:f.items||[]})); setDraft(d.item); }
   if (key==='email') { const d=await request('/admin/settings'); const item=d.item||{}; setData(v=>({...v,settings:item})); const smtpSettings=item.smtp||{}; setSmtp({host:smtpSettings.host||'',port:smtpSettings.port||587,secure:Boolean(smtpSettings.secure),user:smtpSettings.user||'',password:'',fromName:smtpSettings.fromName||'',fromEmail:smtpSettings.fromEmail||'',notificationTo:smtpSettings.notificationTo||'',replyTo:smtpSettings.replyTo||''}); }
   if (key==='documents') { const [d,p,s]=await Promise.all([request('/admin/documents'),request('/admin/packages'),request('/admin/settings')]); setData(v=>({...v,documents:d.items||[],packages:p.items||[],settings:s.item||{}})); }
   if (key==='users') { const d=await request('/admin/users'); setData(v=>({...v,users:d.items||[]})); }
   if (key==='profile') { const [auth,settings]=await Promise.all([request('/admin/auth/me'),request('/admin/settings')]); setUser(auth.user); setProfile(v=>({...v,name:auth.user.name,email:auth.user.email})); const s=settings.item||{}; setSiteSettings({companyName:s.companyName||'FSG Environmental',logoUrl:s.logoUrl||'',website:s.website||'',phone:s.phone||'',email:s.email||'',address:s.address||'',currency:s.currency||'GBP',taxRate:s.taxRate??20,quotePrefix:s.quotePrefix||'FSG-Q',invoicePrefix:s.invoicePrefix||'FSG-I'}); }
  } catch(e) { if (e.message.includes('session') || e.message.includes('sign in')) router.replace('/admin/login'); else fail(e.message); }
  finally { setBusy(false); }
 },[router,tab]);
 useEffect(()=>{ let active=true; request('/admin/auth/me').then(d=>{if(active){setUser(d.user);setProfile({name:d.user.name,email:d.user.email,currentPassword:'',newPassword:''});}}).catch(()=>{if(active)router.replace('/admin/login');}); return ()=>{active=false;}; },[router]);
 useEffect(()=>{if(user) load(tab);},[user,tab,load]);
 const items = data[tab] || [];
 const choose = (item) => { setSelected(item._id); setDraft({...item}); if(tab==='pages')setPageSections(json(item.sections||[])); if(tab==='forms')setFormFields(json(item.fields||[])); if(tab==='packages')setPackageItemsJson(json(item.items||[])); if(tab==='documents'){setDocItemsJson(json(item.items||[]));setDocSendTo(item.customer?.email||'');} if(tab==='enquiries')setReply({to:item.email||'',fromName:'FSG Environmental',fromEmail:'',subject:`Re: FSG project enquiry ${item.reference||''}`,message:''}); setSelectedReplyTemplate(''); setError('');setNotice(''); };
 const newItem = () => {
  const defaults = {pages:DEFAULT_PAGE,branches:DEFAULT_BRANCH,forms:DEFAULT_FORM,templates:DEFAULT_TEMPLATE,packages:{name:'New service package',code:'',description:'',currency:'GBP',taxRate:20,active:true,items:[{description:'Service item',quantity:1,unitPrice:0}]}};
  setSelected(null); setDraft({...defaults[tab]}); if(tab==='pages')setPageSections(DEFAULT_SECTIONS); if(tab==='forms')setFormFields(DEFAULT_FIELDS); if(tab==='packages')setPackageItemsJson(json(defaults.packages.items)); setError('');setNotice('');
 };
 const saveRecord = async (path, body, id=selected) => {
  setBusy(true); try { const payload=JSON.stringify(body); const method=path==='contact-settings'?'PUT':(id?'PUT':'POST'); const suffix=path==='contact-settings'?'':(id?`/${id}`:''); const result=await request(`/admin/${path}${suffix}`,{method,body:payload}); tell('Saved successfully.'); await load(tab); if(result.item){setSelected(result.item._id);setDraft(result.item);} } catch(e){fail(e.message);} finally{setBusy(false);} };
 const deleteRecord = async(path,id)=>{ if(!window.confirm('Delete this record? This action cannot be undone.'))return; setBusy(true); try{await request(`/admin/${path}/${id}`,{method:'DELETE'});setSelected(null);setDraft(null);tell('Record deleted.');await load(tab);}catch(e){fail(e.message);}finally{setBusy(false);} };
 async function logout(){try{await request('/admin/auth/logout',{method:'POST'});}finally{router.replace('/admin/login');}}

 function EditorActions({path,body}){return <div className="admin-actions"><button className="admin-btn primary" disabled={busy} onClick={()=>saveRecord(path,body)}>{busy?'Saving…':'Save changes'}</button>{selected&&path!=='contact-settings'&&<button className="admin-btn danger" onClick={()=>deleteRecord(path,selected)}>Delete</button>}<button className="admin-btn" onClick={()=>{setSelected(null);setDraft(null);}}>Close editor</button></div>;}
 function SideList({list,labelKey='name'}){return <aside className="admin-list"><div className="admin-list-head"><b>{list.length} {tab}</b><button className="admin-btn primary small" onClick={newItem}>+ New</button></div>{list.map(item=><button key={item._id} className={`admin-list-item ${selected===item._id?'active':''}`} onClick={()=>choose(item)}><b>{item[labelKey]||item.title||item.reference}</b><small>{item.slug||item.email||item.status||item.purpose||''}</small></button>)}</aside>;}





 function renderPageEditor(){
  if(!draft)return <EditorEmpty title="Manage website pages" text="Create new pages, edit their sections and publish them to your frontend navigation. Use the section JSON editor to reorder, add, hide or customize the layout blocks."/>;
  let body={...draft}; let sectionError='';
  try{body.sections=JSON.parse(pageSections);if(!Array.isArray(body.sections))throw new Error('Sections must be an array.');}
  catch(e){sectionError=e.message||'Page section JSON is invalid.';}
  return <div className="admin-editor">{pageForm()}<div className="admin-form-grid"><TextArea label="Sections & layout (JSON)" value={pageSections} onChange={setPageSections} rows={24} help="Reorder objects to change frontend order. Each section supports hero, anchorNav, featureSplit, cards, services, steps, cta, richText, faq and form. Use visible:false to hide a block."/></div>{sectionError&&<p className="form-inline-error">{sectionError} Correct the section data before saving.</p>}{!sectionError&&<EditorActions path="pages" body={body}/>}</div>;
  function pageForm(){return <div className="admin-form-grid"><Field label="Page title" value={draft.title} onChange={v=>setDraft({...draft,title:v})}/><Field label="URL slug" value={draft.slug} onChange={v=>setDraft({...draft,slug:v.toLowerCase().replace(/[^a-z0-9-]/g,'-')})}/><Field label="Navigation label" value={draft.navLabel} onChange={v=>setDraft({...draft,navLabel:v})}/><label className="admin-field"><span>Page type</span><select value={draft.pageType||'standard'} onChange={e=>setDraft({...draft,pageType:e.target.value})}><option value="standard">Standard page</option><option value="service">Service page / add to service directory</option></select></label><label className="admin-field"><span>Status</span><select value={draft.status||'draft'} onChange={e=>setDraft({...draft,status:e.target.value})}><option value="draft">Draft</option><option value="published">Published</option></select></label><Field label="Sort order" type="number" value={draft.sortOrder} onChange={v=>setDraft({...draft,sortOrder:Number(v)})}/><Toggle label="Show in main navigation" checked={draft.showInNavigation} onChange={v=>setDraft({...draft,showInNavigation:v})}/><Field label="SEO title" value={draft.seo?.title} onChange={v=>setDraft({...draft,seo:{...draft.seo,title:v}})}/><Field label="SEO description" value={draft.seo?.description} onChange={v=>setDraft({...draft,seo:{...draft.seo,description:v}})}/><Toggle label="No index this page" checked={draft.seo?.noIndex} onChange={v=>setDraft({...draft,seo:{...draft.seo,noIndex:v}})}/></div>;}
 }
 function renderBranchEditor(){if(!draft)return <EditorEmpty title="Manage branches" text="Add, edit, sort and hide branches. Only branches with both Visible and Show on contact enabled will appear on the public contact page."/>;return <div className="admin-editor"><div className="admin-form-grid"><Field label="Branch name" value={draft.name} onChange={v=>setDraft({...draft,name:v})}/><Field label="Label" value={draft.label} onChange={v=>setDraft({...draft,label:v})}/><Field label="Address" value={draft.address} onChange={v=>setDraft({...draft,address:v})}/><Field label="City" value={draft.city} onChange={v=>setDraft({...draft,city:v})}/><Field label="Region / state" value={draft.region} onChange={v=>setDraft({...draft,region:v})}/><Field label="Postcode" value={draft.postalCode} onChange={v=>setDraft({...draft,postalCode:v})}/><Field label="Country" value={draft.country} onChange={v=>setDraft({...draft,country:v})}/><Field label="Phone" value={draft.phone} onChange={v=>setDraft({...draft,phone:v})}/><Field label="Email" value={draft.email} onChange={v=>setDraft({...draft,email:v})}/><Field label="Map URL" value={draft.mapUrl} onChange={v=>setDraft({...draft,mapUrl:v})}/><Field label="Opening hours" value={draft.openingHours} onChange={v=>setDraft({...draft,openingHours:v})}/><Field label="Sort order" type="number" value={draft.sortOrder} onChange={v=>setDraft({...draft,sortOrder:Number(v)})}/><Toggle label="Visible / active" checked={draft.visible} onChange={v=>setDraft({...draft,visible:v})}/><Toggle label="Show on contact page" checked={draft.showOnContact} onChange={v=>setDraft({...draft,showOnContact:v})}/></div><EditorActions path="branches" body={draft}/></div>;}
 function renderFormEditor(){
  if(!draft)return <EditorEmpty title="Create frontend forms" text="Create as many forms as needed, configure fields and connect each form to a page. Assign separate auto-reply and internal notification templates for each form."/>;
  let fields=[];let fieldError='';try{fields=JSON.parse(formFields);if(!Array.isArray(fields))throw new Error('Fields must be an array.');}catch(e){fieldError=e.message||'Form field JSON is invalid.';}
  const body={...draft,fields,pageSlugs:String(draft.pageSlugsText??(draft.pageSlugs||[]).join(',')).split(',').map(x=>x.trim().toLowerCase()).filter(Boolean)};delete body.pageSlugsText;if(!body.autoReplyTemplateId)body.autoReplyTemplateId=null;if(!body.notificationTemplateId)body.notificationTemplateId=null;
  return <div className="admin-editor"><div className="admin-form-grid"><Field label="Form name" value={draft.name} onChange={v=>setDraft({...draft,name:v})}/><Field label="Form slug" value={draft.slug} onChange={v=>setDraft({...draft,slug:v.toLowerCase().replace(/[^a-z0-9-]/g,'-')})}/><Field label="Submit button label" value={draft.submitLabel} onChange={v=>setDraft({...draft,submitLabel:v})}/><label className="admin-field"><span>Publish status</span><select value={draft.status||'draft'} onChange={e=>setDraft({...draft,status:e.target.value})}><option value="draft">Draft</option><option value="published">Published</option></select></label><Field label="Assigned page slugs (comma separated)" value={draft.pageSlugsText??(draft.pageSlugs||[]).join(',')} onChange={v=>setDraft({...draft,pageSlugsText:v})}/><Field label="Description" value={draft.description} onChange={v=>setDraft({...draft,description:v})}/><Field label="Success message" value={draft.successMessage} onChange={v=>setDraft({...draft,successMessage:v})}/><Field label="Grid columns" type="number" value={draft.layout?.columns||2} onChange={v=>setDraft({...draft,layout:{...draft.layout,columns:Math.max(1,Math.min(3,Number(v)))}})}/><Field label="Form background" type="color" value={draft.layout?.formBackground||'#ffffff'} onChange={v=>setDraft({...draft,layout:{...draft.layout,formBackground:v}})}/><Field label="Field background" type="color" value={draft.layout?.fieldBackground||'#fbfcfa'} onChange={v=>setDraft({...draft,layout:{...draft.layout,fieldBackground:v}})}/><Field label="Field border colour" type="color" value={draft.layout?.fieldBorderColor||'#d7e0d6'} onChange={v=>setDraft({...draft,layout:{...draft.layout,fieldBorderColor:v}})}/><Field label="Accent colour" type="color" value={draft.layout?.accentColor||'#238638'} onChange={v=>setDraft({...draft,layout:{...draft.layout,accentColor:v}})}/><Field label="Button background" type="color" value={draft.layout?.buttonBackground||'#61d94e'} onChange={v=>setDraft({...draft,layout:{...draft.layout,buttonBackground:v}})}/><Field label="Button text colour" type="color" value={draft.layout?.buttonTextColor||'#06170c'} onChange={v=>setDraft({...draft,layout:{...draft.layout,buttonTextColor:v}})}/><Field label="Text colour" type="color" value={draft.layout?.textColor||'#101b16'} onChange={v=>setDraft({...draft,layout:{...draft.layout,textColor:v}})}/><Field label="Corner radius (0–16 px)" type="number" value={draft.layout?.borderRadius??0} onChange={v=>setDraft({...draft,layout:{...draft.layout,borderRadius:Math.max(0,Math.min(16,Number(v)))}})}/><label className="admin-field"><span>Auto-reply template</span><select value={draft.autoReplyTemplateId||''} onChange={e=>setDraft({...draft,autoReplyTemplateId:e.target.value})}><option value="">No auto-reply</option>{(data.templates||[]).map(t=><option value={t._id} key={t._id}>{t.name}{t.enabled?'':' (disabled)'}</option>)}</select></label><label className="admin-field"><span>Admin notification template</span><select value={draft.notificationTemplateId||''} onChange={e=>setDraft({...draft,notificationTemplateId:e.target.value})}><option value="">No notification</option>{(data.templates||[]).map(t=><option value={t._id} key={t._id}>{t.name}{t.enabled?'':' (disabled)'}</option>)}</select></label></div><FormFieldsBuilder value={formFields} onChange={setFormFields} submitLabel={draft.submitLabel}/>{fieldError&&<p className="form-inline-error">{fieldError} Correct the field schema before saving.</p>}<div className="admin-actions"><button className="admin-btn primary" disabled={busy||Boolean(fieldError)} onClick={()=>saveRecord('forms',body)}>{busy?'Saving…':'Save form'}</button>{selected&&<button className="admin-btn danger" onClick={()=>deleteRecord('forms',selected)}>Delete</button>}</div></div>;
 }
 function renderTemplateEditor(){if(!draft)return <EditorEmpty title="Reusable email templates" text="Configure automatic replies, enquiry notifications and manual email templates. Arrange the email header, message body and footer independently and use variables to insert client details."/>;return <div className="admin-editor"><div className="admin-form-grid"><Field label="Template name" value={draft.name} onChange={v=>setDraft({...draft,name:v})}/><Field label="Unique key" value={draft.key} onChange={v=>setDraft({...draft,key:v.toLowerCase().replace(/[^a-z0-9-]/g,'-')})}/><label className="admin-field"><span>Purpose</span><select value={draft.purpose} onChange={e=>setDraft({...draft,purpose:e.target.value})}>{['auto-reply','admin-notification','manual-reply','quotation','invoice','custom'].map(x=><option key={x}>{x}</option>)}</select></label><label className="admin-field"><span>Trigger</span><select value={draft.trigger||'manual'} onChange={e=>setDraft({...draft,trigger:e.target.value})}>{['manual','form-submit','lead-created','quotation-created','invoice-created'].map(x=><option key={x}>{x}</option>)}</select></label><Field label="To (supports variables)" value={draft.to} onChange={v=>setDraft({...draft,to:v})} placeholder="{{customer.email}}"/><Field label="CC" value={draft.cc} onChange={v=>setDraft({...draft,cc:v})}/><Field label="BCC" value={draft.bcc} onChange={v=>setDraft({...draft,bcc:v})}/><Field label="From name" value={draft.fromName} onChange={v=>setDraft({...draft,fromName:v})}/><Field label="From email" value={draft.fromEmail} onChange={v=>setDraft({...draft,fromEmail:v})}/><Field label="Reply-to" value={draft.replyTo} onChange={v=>setDraft({...draft,replyTo:v})}/><Field label="Subject" value={draft.subject} onChange={v=>setDraft({...draft,subject:v})}/><Field label="Section order (comma separated)" value={draft.layoutOrderText??(draft.layoutOrder||['header','body','footer']).join(',')} onChange={v=>setDraft({...draft,layoutOrderText:v})}/><Toggle label="Template enabled" checked={draft.enabled} onChange={v=>setDraft({...draft,enabled:v})}/></div><div className="template-arrange"><div className="template-zone"><h3>01 · Header</h3><TextArea label="Header HTML / text" value={draft.headerHtml} onChange={v=>setDraft({...draft,headerHtml:v})} rows={4}/></div><div className="template-zone"><h3>02 · Middle / message body</h3><TextArea label="Body HTML / text" value={draft.bodyHtml} onChange={v=>setDraft({...draft,bodyHtml:v})} rows={9}/></div><div className="template-zone"><h3>03 · Footer</h3><TextArea label="Footer HTML / text" value={draft.footerHtml} onChange={v=>setDraft({...draft,footerHtml:v})} rows={4}/></div></div><div className="variable-reference"><b>Available variables</b><code>{'{{customer.name}} {{customer.email}} {{customer.phone}} {{customer.company}} {{customer.service}} {{form.name}} {{submission.id}} {{fields.siteLocation}} {{company.name}} {{company.notificationEmail}}'}</code><small>Variables are inserted from the customer's submitted details and the enquiry record. Use only simple inline HTML; the email renderer wraps your header, body and footer in the site email frame.</small></div><div className="admin-actions"><button className="admin-btn primary" disabled={busy} onClick={()=>{const body={...draft,layoutOrder:String(draft.layoutOrderText??(draft.layoutOrder||['header','body','footer']).join(',')).split(',').map(x=>x.trim()).filter(x=>['header','body','footer'].includes(x))};delete body.layoutOrderText;saveRecord('email-templates',body);}}>Save template</button>{selected&&<button className="admin-btn" onClick={async()=>{const to=window.prompt('Send a test email to:');if(!to)return;try{await request(`/admin/email-templates/${selected}/test`,{method:'POST',body:JSON.stringify({to})});tell('Test email sent.');}catch(e){fail(e.message);}}}>Send test</button>}{selected&&<button className="admin-btn danger" onClick={()=>deleteRecord('email-templates',selected)}>Delete</button>}</div></div>;}
 function renderContactEditor(){if(!draft)return <EditorEmpty title="Contact page details" text="Manage the contact page headline, introduction, main contact channels, emergency notice and public branch visibility."/>;return <div className="admin-editor"><div className="admin-form-grid"><Field label="Eyebrow" value={draft.eyebrow} onChange={v=>setDraft({...draft,eyebrow:v})}/><Field label="Page title" value={draft.title} onChange={v=>setDraft({...draft,title:v})}/><Field label="Main phone" value={draft.mainPhone} onChange={v=>setDraft({...draft,mainPhone:v})}/><Field label="Main email" value={draft.mainEmail} onChange={v=>setDraft({...draft,mainEmail:v})}/><Field label="Office address" value={draft.address} onChange={v=>setDraft({...draft,address:v})}/><label className="admin-field"><span>Default frontend form</span><select value={draft.defaultFormSlug||'project-scope'} onChange={e=>setDraft({...draft,defaultFormSlug:e.target.value})}>{(data.contactForms||[]).filter(f=>f.status==='published').map(f=><option key={f._id} value={f.slug}>{f.name} · /{f.slug}</option>)}</select></label><Field label="Hero image URL" value={draft.heroImage} onChange={v=>setDraft({...draft,heroImage:v})}/><Field label="Hero primary button" value={draft.heroButtonLabel} onChange={v=>setDraft({...draft,heroButtonLabel:v})}/><Field label="Hero primary link" value={draft.heroButtonHref} onChange={v=>setDraft({...draft,heroButtonHref:v})}/><Field label="Hero secondary button" value={draft.heroSecondaryLabel} onChange={v=>setDraft({...draft,heroSecondaryLabel:v})}/><Field label="Hero secondary link" value={draft.heroSecondaryHref} onChange={v=>setDraft({...draft,heroSecondaryHref:v})}/><Field label="Form section eyebrow" value={draft.formEyebrow} onChange={v=>setDraft({...draft,formEyebrow:v})}/><Field label="Form section heading" value={draft.formTitle} onChange={v=>setDraft({...draft,formTitle:v})}/><TextArea label="Form section introduction" value={draft.formIntro} onChange={v=>setDraft({...draft,formIntro:v})}/><Field label="Branches eyebrow" value={draft.branchesEyebrow} onChange={v=>setDraft({...draft,branchesEyebrow:v})}/><Field label="Branches heading" value={draft.branchesTitle} onChange={v=>setDraft({...draft,branchesTitle:v})}/><TextArea label="Branches introduction" value={draft.branchesIntro} onChange={v=>setDraft({...draft,branchesIntro:v})}/><Field label="Incident section eyebrow" value={draft.incidentEyebrow} onChange={v=>setDraft({...draft,incidentEyebrow:v})}/><Field label="Incident section heading" value={draft.incidentTitle} onChange={v=>setDraft({...draft,incidentTitle:v})}/><TextArea label="Incident information" value={draft.incidentText} onChange={v=>setDraft({...draft,incidentText:v})}/><Field label="Final CTA eyebrow" value={draft.ctaEyebrow} onChange={v=>setDraft({...draft,ctaEyebrow:v})}/><Field label="Final CTA heading" value={draft.ctaTitle} onChange={v=>setDraft({...draft,ctaTitle:v})}/><TextArea label="Final CTA text" value={draft.ctaText} onChange={v=>setDraft({...draft,ctaText:v})}/><Field label="Final CTA button label" value={draft.ctaButtonLabel} onChange={v=>setDraft({...draft,ctaButtonLabel:v})}/><Field label="Final CTA button URL" value={draft.ctaButtonHref} onChange={v=>setDraft({...draft,ctaButtonHref:v})}/><Field label="SEO title" value={draft.seo?.title} onChange={v=>setDraft({...draft,seo:{...draft.seo,title:v}})}/><Field label="SEO description" value={draft.seo?.description} onChange={v=>setDraft({...draft,seo:{...draft.seo,description:v}})}/><Field label="Canonical URL" value={draft.seo?.canonical} onChange={v=>setDraft({...draft,seo:{...draft.seo,canonical:v}})}/><Field label="OpenGraph image URL" value={draft.seo?.ogImage} onChange={v=>setDraft({...draft,seo:{...draft.seo,ogImage:v}})}/><Toggle label="No index contact page" checked={draft.seo?.noIndex} onChange={v=>setDraft({...draft,seo:{...draft.seo,noIndex:v}})}/><TextArea label="Introduction" value={draft.intro} onChange={v=>setDraft({...draft,intro:v})} rows={3}/><TextArea label="Emergency notice" value={draft.emergencyNotice} onChange={v=>setDraft({...draft,emergencyNotice:v})} rows={3}/><Toggle label="Show contact page" checked={draft.contactPageVisible!==false} onChange={v=>setDraft({...draft,contactPageVisible:v})}/><Toggle label="Show branches section" checked={draft.showBranches!==false} onChange={v=>setDraft({...draft,showBranches:v})}/></div><EditorActions path="contact-settings" body={draft}/></div>;}
 function renderEnquiries(){const list=items.filter(x=>!query||`${x.name} ${x.email} ${x.reference} ${x.company}`.toLowerCase().includes(query.toLowerCase()));return <div className="admin-content-grid"><div className="admin-list"><div className="admin-list-head"><b>{list.length} enquiries</b><input className="admin-search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search enquiries"/></div>{list.map(item=><button className={`admin-list-item ${selected===item._id?'active':''}`} key={item._id} onClick={()=>choose(item)}><b>{item.name||'Website enquiry'}</b><small>{item.reference} · {item.email}</small><em>{item.status}</em></button>)}</div><div className="admin-editor">{draft? <><SectionTitle eyebrow={draft.reference||'ENQUIRY'} title={draft.name||'Enquiry details'} desc={`${draft.formName||'Website form'} · ${new Date(draft.createdAt).toLocaleString()}`}/><div className="detail-pairs">{Object.entries(draft.fields||{}).map(([k,v])=><div key={k}><b>{k}</b><span>{Array.isArray(v)?v.join(', '):String(v)}</span></div>)}</div><div className="admin-form-grid"><label className="admin-field"><span>Status</span><select value={draft.status} onChange={e=>setDraft({...draft,status:e.target.value})}>{['new','reviewing','replied','converted','closed'].map(s=><option key={s}>{s}</option>)}</select></label><TextArea label="Internal notes" value={draft.notes} onChange={v=>setDraft({...draft,notes:v})}/></div><div className="admin-actions"><button className="admin-btn primary" onClick={()=>saveRecord('enquiries',{status:draft.status,notes:draft.notes},draft._id)}>Save enquiry</button><button className="admin-btn" onClick={async()=>{try{const d=await request(`/admin/enquiries/${draft._id}/convert-lead`,{method:'POST'});tell('Enquiry converted to a lead.');await load('enquiries');}catch(e){fail(e.message);}}}>Convert to lead</button><button className="admin-btn" onClick={async()=>{try{const d=await request(`/admin/enquiries/${draft._id}/create-quotation`,{method:'POST'});tell('Quotation draft created from this enquiry.');setTab('documents');setSelected(d.item._id);setDraft(d.item);setDocItemsJson(json(d.item.items||[]));setDocSendTo(d.item.customer?.email||'');}catch(e){fail(e.message);}}}>Create quotation</button></div><div className="template-zone"><h3>Send using a configured email template</h3><div className="admin-form-grid"><label className="admin-field"><span>Email template</span><select value={selectedReplyTemplate} onChange={e=>setSelectedReplyTemplate(e.target.value)}><option value="">Choose a template</option>{(data.templates||[]).filter(t=>t.enabled&&['manual-reply','custom','auto-reply'].includes(t.purpose)).map(t=><option value={t._id} key={t._id}>{t.name}</option>)}</select></label><Field label="To override (optional)" value={reply.to} onChange={v=>setReply({...reply,to:v})}/></div><button className="admin-btn primary" disabled={!selectedReplyTemplate} onClick={async()=>{try{await request(`/admin/enquiries/${draft._id}/send-template`,{method:'POST',body:JSON.stringify({templateId:selectedReplyTemplate,to:reply.to||undefined})});tell('Template email sent and recorded.');await load('enquiries');}catch(e){fail(e.message);}}}>Send selected template</button></div><div className="template-zone"><h3>Send a manual email reply</h3><div className="admin-form-grid"><Field label="To" value={reply.to} onChange={v=>setReply({...reply,to:v})}/><Field label="From name" value={reply.fromName} onChange={v=>setReply({...reply,fromName:v})}/><Field label="From email (must match verified SMTP sender)" value={reply.fromEmail} onChange={v=>setReply({...reply,fromEmail:v})}/><Field label="Subject" value={reply.subject} onChange={v=>setReply({...reply,subject:v})}/><TextArea label="Message" value={reply.message} onChange={v=>setReply({...reply,message:v})} rows={6}/></div><button className="admin-btn primary" onClick={async()=>{try{await request(`/admin/enquiries/${draft._id}/send-email`,{method:'POST',body:JSON.stringify(reply)});tell('Email reply sent and recorded.');await load('enquiries');}catch(e){fail(e.message);}}}>Send email reply</button></div></>:<EditorEmpty title="Select an enquiry" text="Review submitted fields, update status, convert it to a lead, or send an email reply."/>}</div></div>;}
 function renderEmailSetup(){return <div className="admin-editor"><SectionTitle eyebrow="EMAIL DELIVERY" title="Configure SMTP delivery" desc="SMTP credentials are encrypted before they are saved. A saved password is never returned to the browser."/><div className="admin-form-grid"><Field label="SMTP host" value={smtp.host} onChange={v=>setSmtp({...smtp,host:v})}/><Field label="SMTP port" type="number" value={smtp.port} onChange={v=>setSmtp({...smtp,port:Number(v)})}/><Field label="SMTP username" value={smtp.user} onChange={v=>setSmtp({...smtp,user:v})}/><Field label="SMTP password / app password" type="password" value={smtp.password} onChange={v=>setSmtp({...smtp,password:v})} placeholder="Leave empty to keep saved password"/><Field label="From name" value={smtp.fromName} onChange={v=>setSmtp({...smtp,fromName:v})}/><Field label="Verified From email" type="email" value={smtp.fromEmail} onChange={v=>setSmtp({...smtp,fromEmail:v})}/><Field label="Notification inbox" type="email" value={smtp.notificationTo} onChange={v=>setSmtp({...smtp,notificationTo:v})}/><Field label="Reply-to email" type="email" value={smtp.replyTo} onChange={v=>setSmtp({...smtp,replyTo:v})}/><Toggle label="Secure TLS (typically port 465)" checked={smtp.secure} onChange={v=>setSmtp({...smtp,secure:v})}/></div><div className="admin-actions"><button className="admin-btn primary" onClick={async()=>{try{await request('/admin/email-settings',{method:'PUT',body:JSON.stringify({smtp})});setSmtp({...smtp,password:''});tell('SMTP settings saved securely.');}catch(e){fail(e.message);}}}>Save email settings</button><button className="admin-btn" onClick={async()=>{const to=window.prompt('Test recipient email:');if(!to)return;try{await request('/admin/email-settings/test',{method:'POST',body:JSON.stringify({to})});tell('Test email sent.');}catch(e){fail(e.message);}}}>Send test email</button></div></div>;}
 function renderProfile(){return <div className="admin-editor"><SectionTitle eyebrow="ADMIN PROFILE" title="Your user settings" desc="Update your display name, login email or password. Changing the password ends the current session."/><div className="admin-form-grid"><Field label="Display name" value={profile.name} onChange={v=>setProfile({...profile,name:v})}/><Field label="Login email" type="email" value={profile.email} onChange={v=>setProfile({...profile,email:v})}/><Field label="Current password (required to change password)" type="password" value={profile.currentPassword} onChange={v=>setProfile({...profile,currentPassword:v})}/><Field label="New password (minimum 12 characters)" type="password" value={profile.newPassword} onChange={v=>setProfile({...profile,newPassword:v})}/></div><button className="admin-btn primary" onClick={async()=>{try{const d=await request('/admin/profile',{method:'PUT',body:JSON.stringify(profile)});tell(d.sessionRevoked?'Profile saved. Sign in again with your new password.':'Profile saved.');if(d.sessionRevoked)router.replace('/admin/login');else setProfile({...profile,currentPassword:'',newPassword:''});}catch(e){fail(e.message);}}}>Save profile</button><div className="template-zone"><h3>Company identity and document defaults</h3><div className="admin-form-grid"><Field label="Company name" value={siteSettings.companyName} onChange={v=>setSiteSettings({...siteSettings,companyName:v})}/><Field label="Logo URL" value={siteSettings.logoUrl} onChange={v=>setSiteSettings({...siteSettings,logoUrl:v})}/><Field label="Website URL" value={siteSettings.website} onChange={v=>setSiteSettings({...siteSettings,website:v})}/><Field label="Company phone" value={siteSettings.phone} onChange={v=>setSiteSettings({...siteSettings,phone:v})}/><Field label="Company email" type="email" value={siteSettings.email} onChange={v=>setSiteSettings({...siteSettings,email:v})}/><Field label="Registered / billing address" value={siteSettings.address} onChange={v=>setSiteSettings({...siteSettings,address:v})}/><Field label="Default currency" value={siteSettings.currency} onChange={v=>setSiteSettings({...siteSettings,currency:v.toUpperCase()})}/><Field label="Default tax rate %" type="number" value={siteSettings.taxRate} onChange={v=>setSiteSettings({...siteSettings,taxRate:Number(v)})}/><Field label="Quotation prefix" value={siteSettings.quotePrefix} onChange={v=>setSiteSettings({...siteSettings,quotePrefix:v})}/><Field label="Invoice prefix" value={siteSettings.invoicePrefix} onChange={v=>setSiteSettings({...siteSettings,invoicePrefix:v})}/></div><button className="admin-btn primary" onClick={async()=>{try{await request('/admin/settings',{method:'PUT',body:JSON.stringify(siteSettings)});tell('Company and document settings saved.');}catch(e){fail(e.message);}}}>Save company settings</button></div></div>;}
 function renderPackageEditor(){if(!draft)return <EditorEmpty title="Service packages" text="Create reusable line-item packages for quotations and invoices. Package items can be reused when drafting customer documents."/>;let body={...draft};try{body.items=JSON.parse(packageItemsJson);delete body.itemsJson;}catch{return <div className="admin-editor"><p className="form-inline-error">Package item JSON is invalid. Correct the JSON before saving.</p><TextArea label="Package line items (JSON)" rows={9} value={packageItemsJson} onChange={setPackageItemsJson}/></div>;}return <div className="admin-editor"><div className="admin-form-grid"><Field label="Package name" value={draft.name} onChange={v=>setDraft({...draft,name:v})}/><Field label="Code" value={draft.code} onChange={v=>setDraft({...draft,code:v})}/><Field label="Currency" value={draft.currency} onChange={v=>setDraft({...draft,currency:v.toUpperCase()})}/><Field label="Tax rate %" type="number" value={draft.taxRate} onChange={v=>setDraft({...draft,taxRate:Number(v)})}/><TextArea label="Description" value={draft.description} onChange={v=>setDraft({...draft,description:v})}/><Toggle label="Active" checked={draft.active} onChange={v=>setDraft({...draft,active:v})}/></div><TextArea label="Package line items (JSON)" rows={9} value={packageItemsJson} onChange={setPackageItemsJson} help="Each row: description, quantity, unitPrice."/><EditorActions path="packages" body={body}/></div>; }
 function renderUsers(){return <div className="admin-editor"><SectionTitle eyebrow="ACCESS CONTROL" title="Manage administrator accounts." desc="Only the owner account can create users or change access roles. Passwords are hashed by the API and are never shown in this list."/><div className="admin-form-grid"><Field label="Full name" value={teamUser.name} onChange={v=>setTeamUser({...teamUser,name:v})}/><Field label="Login email" type="email" value={teamUser.email} onChange={v=>setTeamUser({...teamUser,email:v})}/><Field label="Temporary password (12+ characters)" type="password" value={teamUser.password} onChange={v=>setTeamUser({...teamUser,password:v})}/><label className="admin-field"><span>Role</span><select value={teamUser.role} onChange={e=>setTeamUser({...teamUser,role:e.target.value})}><option value="admin">Admin</option><option value="editor">Editor</option></select></label></div><button className="admin-btn primary" disabled={!teamUser.email||teamUser.password.length<12||busy} onClick={async()=>{try{await request('/admin/users',{method:'POST',body:JSON.stringify(teamUser)});setTeamUser({name:'',email:'',password:'',role:'admin'});tell('Team user created.');await load('users');}catch(e){fail(e.message);}}}>Create team user</button><div className="admin-table-wrap"><table><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Access</th><th>Last login</th></tr></thead><tbody>{(data.users||[]).map(item=><tr key={item._id}><td>{item.name}</td><td>{item.email}</td><td><select value={item.role==='owner'?'owner':item.role} disabled={item.role==='owner'} onChange={async e=>{try{await request(`/admin/users/${item._id}`,{method:'PUT',body:JSON.stringify({role:e.target.value})});await load('users');}catch(er){fail(er.message);}}}><option value="owner">Owner</option><option value="admin">Admin</option><option value="editor">Editor</option></select></td><td><label className="user-status-toggle"><input type="checkbox" checked={Boolean(item.active)} disabled={item.role==='owner'&&String(item._id)===String(user?.id)} onChange={async e=>{try{await request(`/admin/users/${item._id}`,{method:'PUT',body:JSON.stringify({active:e.target.checked})});await load('users');}catch(er){fail(er.message);}}}/>{item.active?'Active':'Disabled'}</label></td><td>{item.lastLoginAt?new Date(item.lastLoginAt).toLocaleString():'Never'}</td></tr>)}</tbody></table></div></div>;}
 function renderDocuments(){
  const docList=data.documents||[];
  const selectedDoc=draft && selected && tab==='documents';
  let items=[]; let parseError=''; try{items=JSON.parse(docItemsJson);}catch{parseError='Line item JSON is invalid.';}
  const body=draft?{...draft,items}:null;
  return <div className="documents-workspace"><div className="admin-doc-toolbar"><div><SectionTitle eyebrow="SALES DOCUMENTS" title="Quotations & invoices" desc="Create documents manually or start a quotation from a project enquiry. Download professional PDF files and email them to the customer."/></div><div className="doc-toolbar-actions"><button className="admin-btn primary" onClick={async()=>{const type=window.confirm('Create an invoice? Choose Cancel for a quotation.')?'invoice':'quotation';try{const d=await request('/admin/documents',{method:'POST',body:JSON.stringify({type,customer:{name:'',email:'',company:'',address:''},currency:data.settings?.currency||'GBP',taxRate:data.settings?.taxRate??20,items:[{description:'Service work',quantity:1,unitPrice:0}],status:'draft'})});tell(`${type} draft created.`);await load('documents');setSelected(d.item._id);setDraft(d.item);setDocItemsJson(json(d.item.items||[]));setDocSendTo('');}catch(e){fail(e.message);}}}>+ New quotation / invoice</button></div></div>
   <div className="document-table">{docList.map(doc=><button className={`document-row ${selected===doc._id?'selected':''}`} key={doc._id} onClick={()=>choose(doc)}><div><b>{doc.number}</b><small>{doc.type} · {doc.customer?.name||'Customer not set'} · {doc.status}</small></div><strong>{doc.currency} {Number(doc.total||0).toFixed(2)}</strong><span className="admin-btn small">Open</span></button>)}</div>
   {selectedDoc ? <div className="admin-editor document-editor"><SectionTitle eyebrow={draft.type==='invoice'?'INVOICE EDITOR':'QUOTATION EDITOR'} title={draft.number} desc="Edit the customer details and line items. The API recalculates tax and totals when saved."/><div className="admin-form-grid"><Field label="Document number" value={draft.number} onChange={v=>setDraft({...draft,number:v})}/><label className="admin-field"><span>Document type</span><select value={draft.type} disabled><option value="quotation">Quotation</option><option value="invoice">Invoice</option></select></label><Field label="Customer name" value={draft.customer?.name} onChange={v=>setDraft({...draft,customer:{...draft.customer,name:v}})}/><Field label="Customer company" value={draft.customer?.company} onChange={v=>setDraft({...draft,customer:{...draft.customer,company:v}})}/><Field label="Customer email" type="email" value={draft.customer?.email} onChange={v=>{setDraft({...draft,customer:{...draft.customer,email:v}});setDocSendTo(v);}}/><Field label="Customer phone" value={draft.customer?.phone} onChange={v=>setDraft({...draft,customer:{...draft.customer,phone:v}})}/><Field label="Customer address" value={draft.customer?.address} onChange={v=>setDraft({...draft,customer:{...draft.customer,address:v}})}/><Field label="Currency (e.g. GBP)" value={draft.currency} onChange={v=>setDraft({...draft,currency:v.toUpperCase()})}/><Field label="Tax rate %" type="number" value={draft.taxRate} onChange={v=>setDraft({...draft,taxRate:Number(v)})}/><Field label="Valid until" type="date" value={draft.validUntil?String(draft.validUntil).slice(0,10):''} onChange={v=>setDraft({...draft,validUntil:v})}/><Field label="Due date" type="date" value={draft.dueDate?String(draft.dueDate).slice(0,10):''} onChange={v=>setDraft({...draft,dueDate:v})}/><label className="admin-field"><span>Status</span><select value={draft.status||'draft'} onChange={e=>setDraft({...draft,status:e.target.value})}>{['draft','sent','accepted','rejected','paid','overdue','cancelled'].map(x=><option key={x}>{x}</option>)}</select></label><label className="admin-field"><span>Insert service package</span><select value="" onChange={e=>{const p=(data.packages||[]).find(x=>x._id===e.target.value);if(p){setDocItemsJson(json(p.items||[]));setDraft({...draft,currency:p.currency||draft.currency,taxRate:p.taxRate??draft.taxRate});}}}><option value="">Choose package</option>{(data.packages||[]).filter(x=>x.active).map(x=><option key={x._id} value={x._id}>{x.name}</option>)}</select></label></div><TextArea label="Line items (JSON)" value={docItemsJson} onChange={setDocItemsJson} rows={9} help="Each item needs description, quantity and unitPrice. Line totals, subtotal and tax are calculated on the server."/>{parseError&&<p className="form-inline-error">{parseError}</p>}<div className="admin-form-grid"><TextArea label="Notes" value={draft.notes} onChange={v=>setDraft({...draft,notes:v})}/><TextArea label="Terms & payment conditions" value={draft.terms} onChange={v=>setDraft({...draft,terms:v})}/></div><div className="document-summary"><span>Current saved total</span><b>{draft.currency||'GBP'} {Number(draft.total||0).toFixed(2)}</b></div><div className="admin-actions"><button className="admin-btn primary" disabled={busy||Boolean(parseError)} onClick={()=>saveRecord('documents',body,draft._id)}>Save document</button><a className="admin-btn" href={`${API}/admin/documents/${draft._id}/pdf`} target="_blank" rel="noreferrer">Download professional PDF</a><button className="admin-btn" onClick={async()=>{const to=docSendTo||draft.customer?.email||window.prompt('Send document to email:');if(!to)return;try{await request(`/admin/documents/${draft._id}/send-email`,{method:'POST',body:JSON.stringify({to})});tell(`PDF emailed to ${to}.`);await load('documents');}catch(e){fail(e.message);}}}>Email PDF to customer</button><button className="admin-btn" onClick={()=>{setSelected(null);setDraft(null);}}>Close</button></div></div> : <div className="admin-empty"><h2>Select or create a document.</h2><p>Open a quotation or invoice to edit client information, line items, tax, payment terms and email delivery.</p></div>}
  </div>;
 }

 const visibleTabs = TABS.filter(([key])=>key!=='users'||user?.role==='owner');
 const currentTab = TABS.find(t=>t[0]===tab);
 return <div className="admin-shell"><aside className="admin-sidebar"><div className="admin-side-brand"><span className="brand-mark">FSG</span><div><b>ENVIRONMENTAL</b><small>ADMIN WORKSPACE</small></div></div><div className="admin-side-caption">MANAGEMENT</div><nav>{visibleTabs.map(([key,label])=><button key={key} className={tab===key?'active':''} onClick={()=>{setTab(key);setSelected(null);setDraft(null);}}>{label}</button>)}</nav><button className="admin-logout" onClick={logout}>Sign out ↗</button><div className="admin-side-user"><b>{user?.name||'Administrator'}</b><small>{user?.email||''}</small></div></aside>
  <div className="admin-main"><header className="admin-topbar"><div><span className="eyebrow">FSG ENVIRONMENTAL / ADMIN</span><h1>{currentTab?.[1]}</h1></div><div className="admin-top-actions"><a href="/" target="_blank" rel="noreferrer">View website ↗</a><button className="admin-btn" onClick={()=>load(tab)}>Refresh</button></div></header>
   {notice&&<div className="admin-alert success">{notice}</div>}{error&&<div className="admin-alert error">{error}</div>}{busy&&<div className="admin-loading">Loading / saving…</div>}
   <div className="admin-page-content">
    {tab==='overview'&&<><SectionTitle eyebrow="WORKSPACE OVERVIEW" title="Your website and enquiries at a glance." desc="Manage public content, customer requests, email templates and service documents."/><div className="metric-grid">{Object.entries(data.overview||{}).map(([k,v])=><div className="metric-card" key={k}><small>{k.replace(/([A-Z])/g,' $1')}</small><strong>{v}</strong></div>)}</div><div className="admin-shortcuts">{visibleTabs.slice(1).map(([key,label])=><button key={key} onClick={()=>setTab(key)}><b>{label}</b><span>Open management →</span></button>)}</div></>}
    {tab==='pages'&&<div className="admin-content-grid"><AdminSideList list={items} labelKey="title" tab={tab} selected={selected} onChoose={choose} onNew={newItem}/>{renderPageEditor()}</div>}
    {tab==='branches'&&<div className="admin-content-grid"><AdminSideList list={items} tab={tab} selected={selected} onChoose={choose} onNew={newItem}/>{renderBranchEditor()}</div>}
    {tab==='contact'&&renderContactEditor()}
    {tab==='forms'&&<div className="admin-content-grid"><AdminSideList list={items} tab={tab} selected={selected} onChoose={choose} onNew={newItem}/>{renderFormEditor()}</div>}
    {tab==='templates'&&<div className="admin-content-grid"><AdminSideList list={items} tab={tab} selected={selected} onChoose={choose} onNew={newItem}/>{renderTemplateEditor()}</div>}
    {tab==='enquiries'&&renderEnquiries()}
    {tab==='leads'&&<div className="admin-table-wrap"><table><thead><tr><th>Lead</th><th>Contact</th><th>Service</th><th>Stage</th><th>Value</th></tr></thead><tbody>{items.map(lead=><tr key={lead._id}><td>{lead.name}</td><td>{lead.email}<br/>{lead.phone}</td><td>{lead.service}</td><td><select value={lead.stage||'new'} onChange={async e=>{try{await request(`/admin/leads/${lead._id}`,{method:'PUT',body:JSON.stringify({stage:e.target.value})});await load('leads');}catch(er){fail(er.message);}}}>{['new','qualified','proposal','won','lost'].map(x=><option key={x}>{x}</option>)}</select></td><td>{lead.value||0}</td></tr>)}</tbody></table></div>}
    {tab==='packages'&&<div className="admin-content-grid"><AdminSideList list={items} tab={tab} selected={selected} onChoose={choose} onNew={newItem}/>{renderPackageEditor()}</div>}
    {tab==='documents'&&renderDocuments()}
    {tab==='email'&&renderEmailSetup()}
    {tab==='profile'&&renderProfile()}
    {tab==='users'&&user?.role==='owner'&&renderUsers()}
   </div>
  </div>
 </div>;
}
function Field({label,value,onChange,type='text',placeholder=''}){return <label className="admin-field"><span>{label}</span><input type={type} value={value??''} placeholder={placeholder} onChange={e=>onChange(e.target.value)}/></label>;}
function TextArea({label,value,onChange,rows=5,help}){return <label className="admin-field"><span>{label}</span><textarea rows={rows} value={value??''} onChange={e=>onChange(e.target.value)}/>{help&&<small>{help}</small>}</label>;}
function Toggle({label,checked,onChange}){return <label className="admin-toggle"><input type="checkbox" checked={Boolean(checked)} onChange={e=>onChange(e.target.checked)}/><span>{label}</span></label>;}
function SectionTitle({eyebrow,title,desc}){return <div className="admin-section-title"><div className="eyebrow">{eyebrow}</div><h2>{title}</h2>{desc&&<p>{desc}</p>}</div>;}
function AdminSideList({list,labelKey='name',tab,selected,onChoose,onNew}){return <aside className="admin-list"><div className="admin-list-head"><b>{list.length} {tab}</b><button className="admin-btn primary small" onClick={onNew}>+ New</button></div>{list.map(item=><button key={item._id} className={`admin-list-item ${selected===item._id?'active':''}`} onClick={()=>onChoose(item)}><b>{item[labelKey]||item.title||item.reference}</b><small>{item.slug||item.email||item.status||item.purpose||''}</small></button>)}</aside>;}
function FormPreview({fields,submitLabel}){return <div className="form-preview"><div className="eyebrow">LIVE FORM PREVIEW</div><h3>{'Form field layout'}</h3><div className="form-preview-grid">{(fields||[]).map((field,i)=><div className={field.width==='full'?'preview-field full':'preview-field'} key={field.key||i}><b>{field.label||'Untitled field'}{field.required?' *':''}</b><div>{field.type==='select'?'Choose an option':field.type==='textarea'?'Long answer area':field.placeholder||field.type||'Text field'}</div></div>)}</div><span className="preview-submit">{submitLabel||'Send request'} ↗</span></div>;}
function EditorEmpty({title,text}){return <div className="admin-editor admin-empty"><div className="eyebrow">CONTENT MANAGEMENT</div><h2>{title}</h2><p>{text}</p><small>Select an item from the left or use “+ New” to create one.</small></div>;}
